package com.mengzhihua.crm.sales.service;
import com.mengzhihua.crm.common.*;import com.mengzhihua.crm.sales.entity.*;import com.mengzhihua.crm.sales.repository.*;import org.springframework.stereotype.Service;import java.time.*;import java.util.*;
@Service public class ActivityService {private final ActivityRepository repo;public ActivityService(ActivityRepository r){repo=r;}public PageResult<Activity> list(int p,int s,String k,Enums.RelatedType t,Long rid,Enums.ActivityStatus st){if(t!=null&&rid!=null)return DtoUtil.page(repo.findByRelatedTypeAndRelatedId(t,rid,DtoUtil.pageable(p,s)),x->(Activity)x);if(st!=null)return DtoUtil.page(repo.findByStatus(st,DtoUtil.pageable(p,s)),x->(Activity)x);return DtoUtil.page(k==null||k.isEmpty()?repo.findAll(DtoUtil.pageable(p,s)):repo.findBySubjectContainingIgnoreCase(k,DtoUtil.pageable(p,s)),x->(Activity)x);}public Activity get(Long id){return repo.findById(id).orElseThrow(()->new BizException("活动不存在"));}public Activity save(Activity x){if(x.getStatus()==null)x.setStatus(Enums.ActivityStatus.PLANNED);return repo.save(x);}public void delete(Long id){repo.deleteById(id);}public Activity complete(Long id){Activity x=get(id);x.setStatus(Enums.ActivityStatus.DONE);x.setCompletedAt(LocalDateTime.now());return repo.save(x);}}
